public void testSignatureToStringWithGenerics_1_oe() throws Exception {
    String a = "java.util.Map<X, java.util.List<Y>>";
    assertEquals("generic signature", a, Utility.signatureToString("Ljava/util/Map<TX;Ljava/util/List<TY;>;>;"));
}

mut_method_definition:
public static String signatureToString( final String signature ) {
        return signatureToString(signature, true);
    }

